{
  "root": "main",
  "state": {
    "itinerary": [
      { "day": "Apr 10", "focus": "Central Kyoto arrival + Gion/Pontocho", "cost": "JPY 28,000", "load": "Low", "rain": "Kyoto National Museum / Nishiki Market arcade", "image": "../assets/r_004551_01_1_A_store_at_Nishiki_market_2C_Kyoto_2C_Japan.jpg" },
      { "day": "Apr 11", "focus": "Arashiyama gardens + temples", "cost": "JPY 34,000", "load": "Moderate-low", "rain": "Tenryu-ji indoor areas / train-and-cafe day" },
      { "day": "Apr 12", "focus": "Higashiyama temples + tea culture", "cost": "JPY 31,000", "load": "Moderate", "rain": "Kyoto City KYOCERA Museum / tea house time", "image": "../assets/r_004551_01_2_Crowds_at_Kyoto_City_Kyocera_Museum_of_Art.jpg" },
      { "day": "Apr 13", "focus": "Day trip to Nara", "cost": "JPY 30,000", "load": "Low-moderate", "rain": "Nara National Museum / indoor temple halls" },
      { "day": "Apr 14", "focus": "Fushimi Inari early + departure", "cost": "JPY 24,000", "load": "Low-moderate", "rain": "Kyoto Railway Museum / hotel lounge morning" }
    ],
    "budget": [
      { "item": "Hotel (4 nights)", "range": "JPY 56k–88k" },
      { "item": "Local transit", "range": "JPY 10k–16k" },
      { "item": "Admissions", "range": "JPY 8k–14k" },
      { "item": "Meals/Snacks", "range": "JPY 48k–70k" },
      { "item": "Taxi support", "range": "JPY 8k–16k" },
      { "item": "Buffer", "range": "JPY 15k–25k" }
    ]
  },
  "elements": {
    "main": { "type": "Stack", "props": { "direction": "vertical", "gap": "md", "padding": 16 }, "children": ["title", "itineraryTable", "budgetTable", "actions"] },
    "title": { "type": "Text", "props": { "text": "Kyoto 5-Day Relaxed Trip Plan", "variant": "h1" }, "children": [] },
    "itineraryTable": {
      "type": "Table",
      "props": {
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "day",
        "statePath": "/itinerary",
        "columns": [
          { "key": "day", "label": "Day" },
          { "key": "focus", "label": "Focus" },
          { "key": "cost", "label": "Cost" },
          { "key": "load", "label": "Walking" },
          { "key": "rain", "label": "Rain Backup" }
        ]
      },
      "children": []
    },
    "budgetTable": {
      "type": "Table",
      "props": {
        "domain": "generic",
        "preferredPresentation": "table",
        "statePath": "/budget",
        "columns": [
          { "key": "item", "label": "Expense" },
          { "key": "range", "label": "Estimate" }
        ]
      },
      "children": []
    },
    "actions": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["btn1", "btn2", "btn3", "btn4"]
    },
    "btn1": { "type": "Button", "props": { "label": "Train routes", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.japan-guide.com/e/e2363.html" } } } }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Kyoto transit", "on": { "press": { "action": "openUrl", "params": { "url": "https://www2.city.kyoto.lg.jp/kotsu/webguide/en/" } } } }, "children": [] },
    "btn3": { "type": "Button", "props": { "label": "Nara access", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.japan-guide.com/e/e2165.html" } } } }, "children": [] },
    "btn4": { "type": "Button", "props": { "label": "Kyoto hotels", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.booking.com/city/jp/kyoto.html" } } } }, "children": [] }
  }
}
